Description: This Terraform configuration provisions a single-node AWS ElastiCache for Redis instance. It creates a dedicated VPC, two public subnets, an internet gateway, routing, a security group allowing Redis access on port `6379`, an ElastiCache subnet group, and a Redis replication group with one cache node.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be deployed."
  type        = string
  default     = "us-east-1"
}

variable "project_name" {
  description = "Project name used for resource naming."
  type        = string
  default     = "redis-demo"
}

variable "redis_node_type" {
  description = "ElastiCache Redis node instance type."
  type        = string
  default     = "cache.t3.micro"
}

variable "redis_engine_version" {
  description = "Redis engine version."
  type        = string
  default     = "7.0"
}

variable "allowed_redis_cidr" {
  description = "CIDR block allowed to connect to Redis."
  type        = string
  default     = "10.0.
